use ss_core::cn::wps::et::ss::statemachine::{StateMachine::StateMachine,RecogniseResultRl::Value};
fn hex(s:&str)->String{s.encode_utf16().map(|u|format!("{u:04x}")).collect()}
fn main(){for line in std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap().lines(){let a=line.split('\t').collect::<Vec<_>>();let input=(0..a[3].len()).step_by(4).map(|i|u16::from_str_radix(&a[3][i..i+4],16).unwrap()).collect::<Vec<_>>();let mut sm=StateMachine::new();sm.setLanguage(a[1].parse().unwrap());sm.setUsing1904(a[2]=="true");let head=a[..4].join("\t");let v=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||sm.parse(&input)));match v{Ok(Some(r))=>{let val=match r.getValue().unwrap(){Value::Number(v)=>format!("{:x}",if v.is_nan(){0x7ff8000000000000}else{v.to_bits()}),Value::Bool(b)=>b.to_string(),Value::Text(v)=>v.iter().map(|u|format!("{u:04x}")).collect()};println!("{head}\t{:?}\t{val}\t{}\t{}",r.getValueType().unwrap(),r.getSuggestedNumfmt().map_or("_".into(),|s|hex(&s)),r.getBuiltInNumfmtIdx());},Ok(None)=>println!("{head}\t_\t_\t_\t-1"),Err(_)=>println!("{head}\tEXCEPTION\tRuntimeException\t_\t-1")}}}
